window.IVIA_KB = {"v":3,"stop":"a an the is are am i me my we our us you your yours to of in on for and or it its this that these those what whats how do does did can could would should will shall be been being with about at as by from have has had any there their them they please tell know want need get some much many which who whom when where why ya hai kya ka ki ke mein ho hain se ko bhi aur also just really very so then than if but not no yes ok okay hmm like into out up down here more most other such only own same too s t now one two help pls plz kindly today currently right","syn":{"fb":"meta facebook","facebook":"meta","insta":"meta instagram","instagram":"meta","ig":"meta instagram","reels":"meta","adword":"google","adwords":"google","pmax":"performance max google","youtube":"google youtube","price":"pricing","prices":"pricing","pricing":"pricing","cost":"pricing","costs":"pricing","fee":"pricing","fees":"pricing","charge":"pricing","charges":"pricing","rate":"pricing","rates":"pricing","package":"pricing","packages":"pricing","quote":"pricing quote","quotation":"pricing quote","kitna":"pricing","kitne":"pricing","paisa":"pricing","expensive":"pricing","cheap":"pricing","afford":"pricing","affordable":"pricing","retainer":"pricing retainer","plan":"pricing","plans":"pricing","flipkart":"marketplace flipkart","meesho":"marketplace","myntra":"marketplace","nykaa":"marketplace","jiomart":"marketplace","ajio":"marketplace","amazon":"amazon marketplace","seller":"amazon marketplace","asin":"amazon","marketplaces":"marketplace","website":"website","site":"website","webpage":"website","landing":"website landing","shopify":"website shopify","wordpress":"website","guaranteed":"guarantee","guarantees":"guarantee","assure":"guarantee","assured":"guarantee","promise":"guarantee","lockin":"contract","agreement":"contract","commitment":"contract","cancel":"contract","notice":"contract","hello":"hi","hey":"hi","hii":"hi","hiii":"hi","namaste":"hi","hola":"hi","heyy":"hi","yo":"hi","thank":"thanks","thx":"thanks","ty":"thanks","shukriya":"thanks","dhanyavad":"thanks","great":"thanks","awesome":"thanks","cool":"thanks","bidvista":"bidvista","bid vista":"bidvista","roi":"roas","return":"roas","acos":"acos","tacos":"tacos","whatsapp":"whatsapp","call":"contact","phone":"contact","number":"contact","reach":"contact","speak":"contact human","talk":"contact human","human":"human contact","person":"human","seo":"seo","rank":"seo ranking","ranking":"seo ranking","google ranking":"seo","ugc":"creative ugc","video":"creative video","videos":"creative video","design":"creative design","shoot":"creative","analytic":"tracking analytics","analytics":"tracking","ga4":"tracking ga4","gtm":"tracking","pixel":"tracking pixel","capi":"tracking capi","mmm":"mmm","mix":"mmm mix","modelling":"mmm","modeling":"mmm","incrementality":"mmm incremental","incremental":"mmm incremental","adstock":"mmm adstock","carryover":"mmm adstock","saturation":"mmm saturation","meridian":"mmm meridian","robyn":"mmm robyn","econometrics":"mmm","klaviyo":"email","newsletter":"email","retention":"email retention","crm":"email","timeline":"time result","soon":"time","quickly":"time","fast":"time","long":"time","minimum":"minimum","min":"minimum","smallest":"minimum","small":"small minimum","start":"start begin","begin":"start","onboard":"start process","onboarding":"start process","proof":"result case","example":"case","portfolio":"case","clients":"client case","client":"client"},"entries":[{"id":"hi","title":"Greeting","k":"hi hello hey good morning good evening good afternoon namaste","q":["hi","hello","hey there"],"a":"Hi, I'm **Ivvy** 👋 Ask me about ivia's services, pricing, results or Bidvista, or tell me what you're trying to grow.","chips":["What do you do?","How much does it cost?","lead:Get a free audit"],"tags":["ivia","chat"]},{"id":"thanks","title":"Thanks","k":"thanks thank you thx helpful great awesome cool nice perfect","q":["thanks","thank you"],"a":"You're welcome! Anything else I can help with?","chips":["lead:Talk to the team","Show me your results"],"tags":["ivia","chat"]},{"id":"bye","title":"Goodbye","k":"bye goodbye see you later cya","q":["bye"],"a":"Thanks for stopping by! If you'd like the team to look at your accounts, the free growth audit is the best place to start.","chips":["lead:Get a free audit"],"tags":["ivia","chat"]},{"id":"bot","title":"Who is Ivvy","k":"ivvy are you human real person bot robot ai chatgpt claude assistant who am i talking to your name","q":["are you a bot","are you human","am i talking to a real person","who is ivvy","what is ivvy","whats your name"],"a":"I'm **Ivvy**, ivia's website assistant: a bot that answers from ivia's own knowledge. For anything about your specific accounts, the team replies within 1 business day, or message us on [WhatsApp](https://wa.me/918607070505).","chips":["wa:Chat with a human","What do you do?"],"tags":["ivia","chat"]},{"id":"about","title":"About ivia","k":"ivia ivia solutions about company agency guys who are you what is ivia what do you do overview introduce","q":["what do you do","what is ivia","who are you","tell me about ivia","about ivia"],"a":"**ivia solutions** is a full-service digital marketing agency. We run **Meta, Google and Amazon ads**, plus creative, SEO, websites, tracking and email/WhatsApp marketing, as **one plan judged on revenue**, not clicks.\nWe also build **Bidvista**, our marketplace AI (early access).","link":"services.html","lt":"See all services","chips":["How much does it cost?","Show me your results","What is Bidvista?"],"tags":["ivia"]},{"id":"team","title":"Who is behind ivia","k":"founder founders owner owners team people behind company legal llp bhavay sanket who runs registered entity","q":["who founded ivia","who is behind ivia","who owns ivia","company name"],"a":"ivia solutions is a brand of **IVIA Marketing Solutions LLP**, built by **Bhavay Sehgal & Sanket Tijare**. Every client gets one named manager with direct WhatsApp access, so you're never passed between rotating teams.","chips":["How do you work?","lead:Talk to the team"],"tags":["ivia"]},{"id":"services","title":"Services","k":"service services offer offering provide list all what can you help with everything channels full service","q":["what services do you offer","services","what can you help with","list your services"],"a":"Here's everything we do. Use one service, or let them work together:\n- [Meta Ads](meta-ads.html): Facebook & Instagram\n- [Google Ads](google-ads.html): Search, Shopping, PMax, YouTube\n- [Amazon & Marketplaces](marketplaces.html): Amazon, Flipkart & more\n- [Creative & Content](creative.html): Video, UGC, statics\n- [Social Media Management](social-media.html): Instagram, LinkedIn, YouTube\n- [SEO & Content](seo.html): Technical, content, local\n- [Websites & Landing Pages](websites.html): Shopify, WordPress, CRO\n- [Analytics & Tracking](analytics-tracking.html): GA4, CAPI, dashboards\n- [Marketing Mix Modelling](marketing-mix-modelling.html): MMM · budget allocation\n- [Email & WhatsApp Marketing](email-whatsapp.html): Flows, campaigns, retention\n- [Bidvista](bidvista.html): our marketplace AI, early access","link":"services.html","lt":"Open services","chips":["How much does it cost?","lead:Get a free audit"],"tags":["ivia"]},{"id":"location","title":"Where are you based","k":"where located based location office city country india address","q":["where are you based","where is your office","where are you located"],"a":"We're an Indian agency working with brands in India and abroad: we manage Amazon in India, the US, the UK and the UAE. Most work happens over WhatsApp, email and video calls, so location is rarely a barrier.","chips":["Which markets do you cover?","lead:Talk to the team"],"tags":["ivia"]},{"id":"industries","title":"Who we work with","k":"industry industries who do you work with type of business d2c ecommerce brand brands startup b2b lead generation fit right for","q":["who do you work with","which industries do you work with","is ivia right for us"],"a":"Mostly **D2C and e-commerce brands** selling on their own site and on marketplaces, plus businesses that grow through **leads**. We're the best fit when you're ready to invest around ₹40,000–₹50,000+ a month in ads and want one team accountable for revenue. Smaller brands can start with a one-time audit, creative, SEO or a website project.","chips":["What is the minimum budget?","lead:Get a free audit"],"tags":["ivia"]},{"id":"pricing","title":"Pricing","k":"pricing price cost fee how much quote package plans retainer charge budget rates engagement","q":["how much does it cost","what are your prices","pricing","what do you charge","how much do you charge"],"a":"Every engagement is **custom-scoped after a free growth audit**, so we don't publish fixed prices. The usual shapes:\n- **Growth Audit**: A one-time, multi-channel diagnostic for brands that want to understand what is working, and what is wasting money, before committing to management.\n- **Performance Retainer**: End-to-end management of the channels you choose (Meta, Google, Amazon or all three) with creative and tracking included. Our most popular engagement.\n- **Launch Package**: For new brands and new products: a coordinated launch across Amazon, Meta and Google, from tracking and landing pages to the first 60 days of campaigns.\nFor ongoing ad management we typically work with brands spending **₹40,000–₹50,000+ a month** on ads.","link":"services.html#s-plans","lt":"See engagement types","chips":["lead:Get a quote","What is the minimum budget?","What's in the free audit?"],"tags":["ivia"],"act":"lead"},{"id":"minspend","title":"Minimum budget","k":"minimum budget ad spend small brand start how much should i spend small budget low budget only have per month 10k 15k 20k 25k 30k lakh limited","q":["what is the minimum budget","minimum ad spend","is there a minimum budget"],"a":"For ongoing ad management we work with brands spending around ₹40,000–₹50,000 a month or more across channels. Below that, management fees become a large share of the budget. One-time audits, creative, SEO and website projects are available for smaller brands.","chips":["How much does it cost?","lead:Get a free audit"],"tags":["ivia"]},{"id":"contract","title":"Contract length","k":"contract minimum term months lock commitment cancel exit notice rolling","q":["what is the minimum contract","is there a lock in","how long is the contract"],"a":"We ask for a 3-month minimum for ongoing management. Month 1 is audit, tracking and restructure; months 2–3 are optimisation and results. Beyond 3 months, we work on a rolling monthly basis with 30 days' notice to exit.","chips":["How do you work?","lead:Talk to the team"],"tags":["ivia"]},{"id":"timeline","title":"How long for results","k":"how long result results time see results weeks months soon fast quickly expect timeline when","q":["how long before i see results","how soon will i see results","when will we see results"],"a":"Tracking fixes and wasted-spend cuts usually show within 2–4 weeks. New Meta and Google campaigns typically need a few weeks of data to stabilise. Amazon organic rank tends to move in weeks 4–8, and SEO compounds over several months. We set specific expectations after the audit.","chips":["Do you guarantee results?","Show me your results"],"tags":["ivia"]},{"id":"guarantee","title":"Guarantees","k":"guarantee guaranteed promise assured result results sure","q":["do you guarantee results","can you guarantee results"],"a":"No, and any agency that does is making a promise it cannot keep. Ad auctions on Meta, Google and Amazon are dynamic. We commit to a rigorous documented process, clear KPI targets agreed upfront, and honest communication when performance diverges from plan.","chips":["Show me your results","How do you report?"],"tags":["ivia"]},{"id":"access","title":"Account access","k":"access account accounts password ownership own business manager admin permissions login","q":["what access do you need","do you need our password","who owns the ad accounts"],"a":"Partner access through Meta Business Manager, a link to our Google Ads manager account, Campaign Manager access on Amazon Ads, and GA4 / Tag Manager access where we handle tracking. You keep ownership of every account, and we never need your passwords.","chips":["How do you work?"],"tags":["ivia"]},{"id":"markets","title":"Channels & markets","k":"channel channels marketplace marketplaces cover country countries market markets india us uk uae usa international global","q":["which channels do you cover","which markets do you cover","do you work outside india"],"a":"Meta (Facebook & Instagram), Google (Search, Shopping, Performance Max and YouTube), Amazon India, US, UK and UAE, plus Flipkart and other marketplaces. Alongside ads we handle creative, social media, SEO, websites, tracking and email/WhatsApp marketing.","chips":["Amazon & marketplaces","Meta Ads","Google Ads"],"tags":["ivia"]},{"id":"audit","title":"Free growth audit","k":"audit free growth audit check review diagnostic analyse analyze account included report","q":["whats in the free audit","what is the growth audit","is the audit free","get a free audit","audit my account"],"a":"Every engagement starts with a **free, no-obligation growth audit**. We look at:\n- Tracking accuracy: Pixel, CAPI, GA4, Google Ads\n- Account & campaign structure\n- Wasted spend: search terms & placements\n- Audience overlap & targeting\n- Creative fatigue & testing cadence\n- Landing page & listing conversion rate\n- Attribution & reporting setup\n- Negative keyword coverage\n- Budget split across channels\n- Bid strategy & learning-phase health\nYou get a prioritised action plan. If you only want the written audit without ongoing management, ask for the one-time **Growth Audit**.","link":"contact.html","lt":"Request an audit","chips":["lead:Yes, audit my accounts","How long does it take?"],"tags":["ivia"],"act":"lead"},{"id":"process","title":"How we work","k":"process how do you work steps onboarding start begin workflow method approach first","q":["how do you work","what is your process","how do we start","how does onboarding work"],"a":"Audit first, then scale:\n1. **Discovery Call**: 30 mins on your products, margins, goals and the channels you run today.\n2. **Growth Audit**: Tracking, ad accounts, creative and landing pages reviewed. Written findings in 5–7 days.\n3. **Strategy & Channel Plan**: Agree KPIs, budgets and which channel does which job before any money moves.\n4. **Build & Tracking Setup**: Campaigns, tracking and dashboards built in parallel, with no disruption to what already works.\n5. **Weekly Optimisation**: Bids, budgets, negatives and creative rotation, with every change logged in plain language.\n6. **Monthly Strategy Review**: Blended performance vs targets, creative learnings and next month's plan.","chips":["How do you report?","lead:Start with an audit"],"tags":["ivia"]},{"id":"reporting","title":"Reporting","k":"report reporting reports dashboard weekly monthly update updates communication action log transparency looker manager whatsapp","q":["how do you report","what reports do we get","what reports will i get","how often will we get updates"],"a":"You always know what changed and why:\n- **Weekly action log**: every change, in plain language\n- **Monthly strategy review** against agreed targets\n- **Live Looker Studio dashboard** with blended ROAS, MER and CAC\n- **One named manager** on direct WhatsApp","chips":["What is MER?","How do you work?"],"tags":["ivia"]},{"id":"contact","title":"Contact","k":"contact email phone number whatsapp call reach talk human speak team address get in touch","q":["how can i contact you","contact","phone number","whatsapp number","email address","talk to a human"],"a":"- Email: connect@bidvista.org\n- WhatsApp: [+91 86070 70505](https://wa.me/918607070505) (fastest)\n- Or use the [contact form](contact.html)\nWe reply within **1 business day**.","link":"contact.html","lt":"Contact page","chips":["wa:Chat on WhatsApp","lead:Leave my details"],"tags":["ivia","chat"]},{"id":"reply","title":"Reply time","k":"reply response time how fast respond answer back when will you reply","q":["how fast do you reply","when will you get back to me"],"a":"Within **1 business day** by email or the contact form. WhatsApp ([+91 86070 70505](https://wa.me/918607070505)) is usually fastest.","chips":["wa:Chat on WhatsApp","lead:Leave my details"],"tags":["ivia","chat"]},{"id":"results","title":"Results & case studies","k":"result results case case studies study proof clients examples success acos reduction roas improvement numbers track record","q":["show me your results","case studies","do you have results","what results have you achieved"],"a":"Anonymised results from accounts we manage:\n- **44%** average ACOS reduction across managed Amazon accounts\n- **65%** average ROAS improvement after restructures\n- Home lighting: ACOS **70% → 39%** after a full restructure\n- Pet supplies: **+80%** revenue without raising ACOS\n- Skincare launch: **0 → 12** page-1 keywords in 75 days\n- Multi-SKU portfolio: TACOS **31% → 20%** across 40+ ASINs\n- **₹1Cr+** ad spend under management","link":"case-studies.html","lt":"View case studies","chips":["How do you measure success?","lead:Get a free audit"],"tags":["ivia","mkt"]},{"id":"why","title":"Why ivia","k":"why choose different better than other agencies agency unique difference why you","q":["why ivia","why should we choose you","what makes you different"],"a":"What makes ivia different:\n- **Audit before every rupee**: We diagnose before we prescribe. No spending until we know what's broken, on every channel, and why.\n- **One plan across every channel**: Meta, Google and Amazon run as one strategy and are judged on blended results, not three agencies defending three dashboards.\n- **Weekly action logs**: Every change documented in plain language. You always know what happened and why.\n- **Named manager · direct WhatsApp**: One person owns your account. No rotating teams, no ticket queues.","chips":["Show me your results","lead:Get a free audit"],"tags":["ivia"]},{"id":"tools","title":"Tools","k":"tools software stack included helium looker studio platform extra cost hidden","q":["what tools do you use","are tools included"],"a":"The tools we use to run and report on your accounts are **included in the fee**, with no hidden software costs: Meta Ads Manager, Google Ads, Amazon Ads, Google Analytics 4, Google Tag Manager, Looker Studio, Merchant Center, Helium 10, Microsoft Clarity.","chips":["How do you report?"],"tags":["ivia"]},{"id":"careers","title":"Careers","k":"job jobs career careers hiring hire work for you internship vacancy","q":["are you hiring","job openings"],"a":"Thanks for your interest! Send your CV or portfolio to connect@bidvista.org and we'll get back to you.","tags":["ivia","chat"]},{"id":"fiverr","title":"Fiverr","k":"fiverr fiverr pro gig hire freelance","q":["are you on fiverr"],"a":"Yes, we're on Fiverr Pro for Amazon PPC management: [view our Fiverr profile](https://pro.fiverr.com/bhavay0011/setup-optimize-and-manage-your-amazon-ppc-campaign-ads?ref_ctx_id=9aceecbcbec446fc93219ac42d74f837&pckg_id=1&source=business_seller_page). For full-service work, contacting us directly is best.","tags":["ivia","mkt"]},{"id":"blog","title":"Blog","k":"blog article articles guide guides learn read resources tips","q":["do you have a blog","where can i learn more"],"a":"Our [blog](blog.html) has in-depth guides on Meta Ads structure, Google Search vs Performance Max, tracking setup, creative testing, ROAS vs MER vs CAC and 9 Amazon PPC guides.","link":"blog.html","lt":"Open the blog","tags":["ivia"]},{"id":"svc_meta","title":"Meta Ads","k":"meta facebook instagram fb insta ig reels advantage catalog lead ads social ads meta ads demand creation prospecting lead generation catalog ads included include service services management agency","q":["what's included in meta ads","what's included in Meta Ads","meta ads","tell me about meta ads","do you do meta ads"],"a":"**Meta Ads**: People on Instagram and Facebook are not searching for you; great ads introduce you to them. We build consolidated account structures that give Meta's algorithm enough signal to learn, let creative do the targeting, and test new concepts every week so performance does not fade.\nWhat's included:\n- Account audit and consolidation: fewer ad sets, each able to exit the learning phase\n- Broad, creative-led prospecting with a separate creative-testing campaign\n- Catalog and dynamic product ads for e-commerce\n- Lead-form and website lead campaigns, with qualified leads fed back from your CRM\n- Meta Pixel + Conversions API with event deduplication","link":"meta-ads.html","lt":"Open Meta Ads","chips":["What budget do I need for Meta ads?","Do you make the ads too?","lead:Get a free audit"],"tags":["ivia"],"svc":"meta"},{"id":"faq_meta_0","title":"What budget do I need for Meta ads?","k":"what budget do i need for meta ads ","q":["What budget do I need for Meta ads?"],"a":"For ongoing management we work with brands spending around ₹40,000–₹50,000 a month or more across channels. On Meta, each ad set needs enough budget to get regular conversions, so we often run fewer campaigns rather than splitting a small budget thin. We recommend a starting budget after the audit.","link":"meta-ads.html","lt":"Open Meta Ads","chips":["Do you make the ads too?","Should we use Advantage+ shopping campaigns?","lead:Get a free audit"],"tags":["ivia"],"svc":"meta"},{"id":"faq_meta_1","title":"Do you make the ads too?","k":"do you make the ads too ","q":["Do you make the ads too?"],"a":"Yes. Creative production is part of the performance retainer: hook-first videos, UGC-style ads and statics in monthly sprints. If you have an in-house team or creators, we brief them and run the testing.","link":"meta-ads.html","lt":"Open Meta Ads","chips":["What budget do I need for Meta ads?","Should we use Advantage+ shopping campaigns?","lead:Get a free audit"],"tags":["ivia"],"svc":"meta"},{"id":"faq_meta_2","title":"Should we use Advantage+ shopping campaigns?","k":"should we use advantage  shopping campaigns ","q":["Should we use Advantage+ shopping campaigns?"],"a":"Often yes for e-commerce, alongside a separate creative-testing setup so you still learn which concepts win. We decide after looking at your catalog, data volume and how much control you need over new versus returning customers.","link":"meta-ads.html","lt":"Open Meta Ads","chips":["What budget do I need for Meta ads?","Do you make the ads too?","lead:Get a free audit"],"tags":["ivia"],"svc":"meta"},{"id":"faq_meta_3","title":"How soon will Meta ads show results?","k":"how soon will meta ads show results ","q":["How soon will Meta ads show results?"],"a":"Tracking and structure fixes can improve efficiency within the first few weeks. New campaigns usually need a few weeks of data to stabilise, and creative testing compounds month over month. We set specific expectations after the audit.","link":"meta-ads.html","lt":"Open Meta Ads","chips":["What budget do I need for Meta ads?","Do you make the ads too?","lead:Get a free audit"],"tags":["ivia"],"svc":"meta"},{"id":"svc_google","title":"Google Ads","k":"google adwords search shopping pmax performance max youtube demand gen merchant center feed ppc google ads intent capture search shopping performance max youtube included include service services management agency","q":["what's included in google ads","what's included in Google Ads","google ads","tell me about google ads","do you do google ads"],"a":"**Google Ads**: When someone searches for your category, your brand or the problem you solve, you should be there. We structure Search campaigns for control, run Shopping and Performance Max with clean feeds and brand exclusions, and use YouTube to reach people before they search.\nWhat's included:\n- Keyword and intent research with separate brand, non-brand and competitor campaigns\n- Negative keyword management and search-term reviews every week\n- Merchant Center feed optimisation: titles, GTINs, images, disapprovals\n- Performance Max with brand exclusions and asset-group strategy\n- YouTube and Demand Gen campaigns for reach and remarketing","link":"google-ads.html","lt":"Open Google Ads","chips":["Search or Performance Max: which should we run?","Should we bid on our own brand name?","lead:Get a free audit"],"tags":["ivia"],"svc":"google"},{"id":"faq_google_0","title":"Search or Performance Max: which should we run?","k":"search or performance max  which should we run ","q":["Search or Performance Max: which should we run?"],"a":"Usually both, with clear roles. Search gives control over exactly which queries you pay for; Performance Max can find extra conversions across Google's inventory. We run PMax with brand exclusions and a clean feed so it doesn't simply take credit for brand searches.","link":"google-ads.html","lt":"Open Google Ads","chips":["Should we bid on our own brand name?","Do you manage Google Shopping feeds?","lead:Get a free audit"],"tags":["ivia"],"svc":"google"},{"id":"faq_google_1","title":"Should we bid on our own brand name?","k":"should we bid on our own brand name ","q":["Should we bid on our own brand name?"],"a":"It depends on whether competitors bid on it and what it costs. Brand campaigns are usually cheap and protect your top result, but we report them separately so they don't flatter overall performance.","link":"google-ads.html","lt":"Open Google Ads","chips":["Search or Performance Max: which should we run?","Do you manage Google Shopping feeds?","lead:Get a free audit"],"tags":["ivia"],"svc":"google"},{"id":"faq_google_2","title":"Do you manage Google Shopping feeds?","k":"do you manage google shopping feeds ","q":["Do you manage Google Shopping feeds?"],"a":"Yes. Merchant Center setup, feed optimisation (titles, attributes, GTINs, images) and fixing disapprovals are part of Google Ads management for e-commerce brands.","link":"google-ads.html","lt":"Open Google Ads","chips":["Search or Performance Max: which should we run?","Should we bid on our own brand name?","lead:Get a free audit"],"tags":["ivia"],"svc":"google"},{"id":"faq_google_3","title":"Do you work with lead-generation businesses?","k":"do you work with lead generation businesses ","q":["Do you work with lead-generation businesses?"],"a":"Yes. For lead gen we track qualified leads, not just form fills, and where possible import offline conversions from your CRM so Google optimises for leads that become revenue.","link":"google-ads.html","lt":"Open Google Ads","chips":["Search or Performance Max: which should we run?","Should we bid on our own brand name?","lead:Get a free audit"],"tags":["ivia"],"svc":"google"},{"id":"svc_amazon","title":"Amazon & Marketplaces","k":"amazon marketplace marketplaces flipkart ppc sponsored products brands display seller central asin listing acos tacos meesho myntra nykaa amazon   marketplaces marketplace growth sponsored products sponsored brands display included include service services management agency","q":["what's included in amazon & marketplaces","what's included in Amazon & Marketplaces","amazon & marketplaces","tell me about amazon & marketplaces","do you do amazon & marketplaces"],"a":"**Amazon & Marketplaces**: This is where we started. Every Amazon account begins with a 15-point audit, then a three-tier campaign architecture (Discovery, Qualification, Dominance) with bids calculated, not guessed: Target ACOS × CVR × Price = Target CPC. The same discipline extends to Flipkart and other marketplaces.\nWhat's included:\n- 15-point PPC audit with a written, prioritised action plan in 5–7 days\n- Three-tier keyword and campaign architecture per SKU\n- Weekly bid reviews, placement modifiers and negative keyword additions\n- Search-term harvesting from discovery into exact match\n- 60-day product launch playbook for new ASINs","link":"marketplaces.html","lt":"Open Amazon & Marketplaces","chips":["Which marketplaces do you manage?","What is the difference between ACOS and TACOS?","lead:Get a free audit"],"tags":["ivia","mkt"],"svc":"amazon"},{"id":"faq_amazon_0","title":"Which marketplaces do you manage?","k":"which marketplaces do you manage ","q":["Which marketplaces do you manage?"],"a":"Amazon India, US, UK and UAE, plus Flipkart and other marketplaces. The same audit-first, calculated-bid approach applies everywhere; the tools and ad types differ by platform.","link":"marketplaces.html","lt":"Open Amazon & Marketplaces","chips":["What is the difference between ACOS and TACOS?","Can you help launch a new product on Amazon?","lead:Get a free audit"],"tags":["ivia","mkt"],"svc":"amazon"},{"id":"faq_amazon_1","title":"What is the difference between ACOS and TACOS?","k":"what is the difference between acos and tacos ","q":["What is the difference between ACOS and TACOS?"],"a":"ACOS is ad spend divided by ad-attributed sales. TACOS is ad spend divided by total sales, including organic. If TACOS falls while sales grow, ads are building organic rank; if it rises, you are buying sales rather than building them.","link":"marketplaces.html","lt":"Open Amazon & Marketplaces","chips":["Which marketplaces do you manage?","Can you help launch a new product on Amazon?","lead:Get a free audit"],"tags":["ivia","mkt"],"svc":"amazon"},{"id":"faq_amazon_2","title":"Can you help launch a new product on Amazon?","k":"can you help launch a new product on amazon ","q":["Can you help launch a new product on Amazon?"],"a":"Yes. Our 60-day launch playbook covers listing readiness, keyword selection, launch bids and coordination with review programmes such as Vine, aiming to build enough sales velocity for organic rank.","link":"marketplaces.html","lt":"Open Amazon & Marketplaces","chips":["Which marketplaces do you manage?","What is the difference between ACOS and TACOS?","lead:Get a free audit"],"tags":["ivia","mkt"],"svc":"amazon"},{"id":"svc_creative","title":"Creative & Content","k":"creative content video ugc reels shorts static statics carousel design hook hooks listing images a+ thumbnail shoot edit creative   content creative engine video ugc statics listing images included include service services management agency","q":["what's included in creative & content","what's included in Creative & Content","creative & content","tell me about creative & content","do you do creative & content"],"a":"**Creative & Content**: On Meta and YouTube, creative is now the biggest performance lever. We plan concepts from customer insight, script hook-first videos, produce UGC-style ads and statics, and run a testing system that tells you which ideas win and why.\nWhat's included:\n- Monthly creative sprints: new concepts, not just variations\n- Hook-first video scripts and edits for Reels, Shorts and in-feed\n- UGC-style and founder-led ads\n- Static ads, carousels and Amazon listing / A+ images\n- Creative testing framework with clear scale-or-kill rules","link":"creative.html","lt":"Open Creative & Content","chips":["Do you work with creators and influencers?","How many new creatives do we need each month?","lead:Get a free audit"],"tags":["ivia"],"svc":"creative"},{"id":"faq_creative_0","title":"Do you work with creators and influencers?","k":"do you work with creators and influencers ","q":["Do you work with creators and influencers?"],"a":"Yes. We write briefs and scripts for UGC creators, review the footage and edit it into ads. We can source creators or work with ones you already have.","link":"creative.html","lt":"Open Creative & Content","chips":["How many new creatives do we need each month?","Can you make Amazon listing images and A+ content?","lead:Get a free audit"],"tags":["ivia"],"svc":"creative"},{"id":"faq_creative_1","title":"How many new creatives do we need each month?","k":"how many new creatives do we need each month ","q":["How many new creatives do we need each month?"],"a":"It depends on spend and channel: bigger budgets fatigue creative faster and need more new concepts. We set a monthly sprint size after the audit, focused on genuinely new ideas rather than many small variations.","link":"creative.html","lt":"Open Creative & Content","chips":["Do you work with creators and influencers?","Can you make Amazon listing images and A+ content?","lead:Get a free audit"],"tags":["ivia"],"svc":"creative"},{"id":"faq_creative_2","title":"Can you make Amazon listing images and A+ content?","k":"can you make amazon listing images and a  content ","q":["Can you make Amazon listing images and A+ content?"],"a":"Yes. Listing images, infographics and A+ content are part of creative production, and are often the cheapest conversion-rate win on a marketplace.","link":"creative.html","lt":"Open Creative & Content","chips":["Do you work with creators and influencers?","How many new creatives do we need each month?","lead:Get a free audit"],"tags":["ivia"],"svc":"creative"},{"id":"faq_creative_3","title":"Do you only make ads, or brand content too?","k":"do you only make ads  or brand content too ","q":["Do you only make ads, or brand content too?"],"a":"Our focus is performance creative: ads that are tested and judged on results. Organic social content is covered by our social media service, and we keep the two consistent.","link":"creative.html","lt":"Open Creative & Content","chips":["Do you work with creators and influencers?","How many new creatives do we need each month?","lead:Get a free audit"],"tags":["ivia"],"svc":"creative"},{"id":"svc_social","title":"Social Media Management","k":"social media smm organic instagram linkedin youtube posting posts calendar community dm comments followers handle page management social media management always-on brand instagram linkedin youtube included include service services management agency","q":["what's included in social media management","what's included in Social Media Management","social media management","tell me about social media management","do you do social media management"],"a":"**Social Media Management**: Your organic social is often the first thing a prospect checks after seeing an ad. We run content calendars, posting and community management that look consistent with your paid campaigns and build trust over time.\nWhat's included:\n- Monthly content calendar and approvals workflow\n- Posting and scheduling across Instagram, LinkedIn and YouTube\n- Reels and short-form video aligned with paid creative\n- Community management: comments and DMs\n- Monthly performance report in plain language","link":"social-media.html","lt":"Open Social Media Management","chips":["Which social platforms do you manage?","Do we approve posts before they go live?","lead:Get a free audit"],"tags":["ivia"],"svc":"social"},{"id":"faq_social_0","title":"Which social platforms do you manage?","k":"which social platforms do you manage ","q":["Which social platforms do you manage?"],"a":"Instagram, LinkedIn and YouTube most often. We recommend focusing on the one or two platforms where your customers actually spend time rather than posting everywhere.","link":"social-media.html","lt":"Open Social Media Management","chips":["Do we approve posts before they go live?","Will organic social grow our sales?","lead:Get a free audit"],"tags":["ivia"],"svc":"social"},{"id":"faq_social_1","title":"Do we approve posts before they go live?","k":"do we approve posts before they go live ","q":["Do we approve posts before they go live?"],"a":"Yes. The monthly calendar is shared for approval before anything is scheduled.","link":"social-media.html","lt":"Open Social Media Management","chips":["Which social platforms do you manage?","Will organic social grow our sales?","lead:Get a free audit"],"tags":["ivia"],"svc":"social"},{"id":"faq_social_2","title":"Will organic social grow our sales?","k":"will organic social grow our sales ","q":["Will organic social grow our sales?"],"a":"Organic social builds trust and supports conversion, but it rarely drives large sales volume on its own. We treat it as part of the funnel alongside paid ads, and report on the metrics that show intent.","link":"social-media.html","lt":"Open Social Media Management","chips":["Which social platforms do you manage?","Do we approve posts before they go live?","lead:Get a free audit"],"tags":["ivia"],"svc":"social"},{"id":"faq_social_3","title":"Can you also run our social ads?","k":"can you also run our social ads ","q":["Can you also run our social ads?"],"a":"Yes. Social media management pairs naturally with Meta Ads, and keeping both in one team keeps the brand consistent.","link":"social-media.html","lt":"Open Social Media Management","chips":["Which social platforms do you manage?","Do we approve posts before they go live?","lead:Get a free audit"],"tags":["ivia"],"svc":"social"},{"id":"svc_seo","title":"SEO & Content","k":"seo search engine optimisation optimization organic ranking rank google ranking keywords content blog local gmb business profile backlinks technical seo   content compounding traffic technical seo content local seo included include service services management agency","q":["what's included in seo & content","what's included in SEO & Content","seo & content","tell me about seo & content","do you do seo & content"],"a":"**SEO & Content**: Paid traffic stops the day you stop paying. SEO compounds. We fix the technical foundations, target the searches your customers actually make, and publish content that earns rankings, so a growing share of revenue does not depend on ad spend.\nWhat's included:\n- Technical audit: speed, indexing, structure, Core Web Vitals\n- Keyword strategy mapped to commercial intent\n- On-page optimisation for product, category and service pages\n- Content plan and articles written for search and for people\n- Google Business Profile and local SEO where relevant","link":"seo.html","lt":"Open SEO & Content","chips":["How long does SEO take?","Do you write the SEO content?","lead:Get a free audit"],"tags":["ivia"],"svc":"seo"},{"id":"faq_seo_0","title":"How long does SEO take?","k":"how long does seo take ","q":["How long does SEO take?"],"a":"Technical fixes can show results within weeks, but meaningful growth usually builds over several months. SEO compounds: work done this quarter keeps paying back long after.","link":"seo.html","lt":"Open SEO & Content","chips":["Do you write the SEO content?","Do you do local SEO?","lead:Get a free audit"],"tags":["ivia"],"svc":"seo"},{"id":"faq_seo_1","title":"Do you write the SEO content?","k":"do you write the seo content ","q":["Do you write the SEO content?"],"a":"Yes. We plan topics from keyword research and write articles and page copy, reviewed with you for accuracy.","link":"seo.html","lt":"Open SEO & Content","chips":["How long does SEO take?","Do you do local SEO?","lead:Get a free audit"],"tags":["ivia"],"svc":"seo"},{"id":"faq_seo_2","title":"Do you do local SEO?","k":"do you do local seo ","q":["Do you do local SEO?"],"a":"Yes, where relevant: Google Business Profile optimisation, local landing pages and consistent business listings.","link":"seo.html","lt":"Open SEO & Content","chips":["How long does SEO take?","Do you write the SEO content?","lead:Get a free audit"],"tags":["ivia"],"svc":"seo"},{"id":"faq_seo_3","title":"Can you guarantee first position on Google?","k":"can you guarantee first position on google ","q":["Can you guarantee first position on Google?"],"a":"No one can honestly guarantee rankings; Google decides. We commit to a clear plan, steady execution and reporting on organic traffic and conversions.","link":"seo.html","lt":"Open SEO & Content","chips":["How long does SEO take?","Do you write the SEO content?","lead:Get a free audit"],"tags":["ivia"],"svc":"seo"},{"id":"svc_web","title":"Websites & Landing Pages","k":"website websites web site landing page pages shopify wordpress cro conversion rate optimisation optimization design develop build store ecommerce checkout speed websites   landing pages conversion shopify wordpress landing pages included include service services management agency","q":["what's included in websites & landing pages","what's included in Websites & Landing Pages","websites & landing pages","tell me about websites & landing pages","do you do websites & landing pages"],"a":"**Websites & Landing Pages**: Doubling your conversion rate halves your cost per customer on every channel at once. We build fast, focused landing pages and websites, then test headlines, offers and layouts so the traffic you pay for turns into revenue.\nWhat's included:\n- Conversion-focused landing pages for campaigns and offers\n- Shopify and WordPress builds and improvements\n- Page-speed and mobile experience fixes\n- A/B testing of headlines, offers and page layouts\n- Forms and checkout friction review","link":"websites.html","lt":"Open Websites & Landing Pages","chips":["Do you build on Shopify and WordPress?","Do we need a full website redesign?","lead:Get a free audit"],"tags":["ivia"],"svc":"web"},{"id":"faq_web_0","title":"Do you build on Shopify and WordPress?","k":"do you build on shopify and wordpress ","q":["Do you build on Shopify and WordPress?"],"a":"Yes, both, plus custom-built pages when a campaign needs something specific.","link":"websites.html","lt":"Open Websites & Landing Pages","chips":["Do we need a full website redesign?","How do you know a change worked?","lead:Get a free audit"],"tags":["ivia"],"svc":"web"},{"id":"faq_web_1","title":"Do we need a full website redesign?","k":"do we need a full website redesign ","q":["Do we need a full website redesign?"],"a":"Often not. Focused landing pages and fixes to the biggest drop-off points usually deliver faster gains than a full rebuild.","link":"websites.html","lt":"Open Websites & Landing Pages","chips":["Do you build on Shopify and WordPress?","How do you know a change worked?","lead:Get a free audit"],"tags":["ivia"],"svc":"web"},{"id":"faq_web_2","title":"How do you know a change worked?","k":"how do you know a change worked ","q":["How do you know a change worked?"],"a":"We A/B test where traffic allows, and otherwise compare before and after with analytics, heatmaps and recordings.","link":"websites.html","lt":"Open Websites & Landing Pages","chips":["Do you build on Shopify and WordPress?","Do we need a full website redesign?","lead:Get a free audit"],"tags":["ivia"],"svc":"web"},{"id":"faq_web_3","title":"Will you set up tracking on new pages?","k":"will you set up tracking on new pages ","q":["Will you set up tracking on new pages?"],"a":"Yes. Every page we build ships with GA4 events and ad-platform conversions in place.","link":"websites.html","lt":"Open Websites & Landing Pages","chips":["Do you build on Shopify and WordPress?","Do we need a full website redesign?","lead:Get a free audit"],"tags":["ivia"],"svc":"web"},{"id":"svc_tracking","title":"Analytics & Tracking","k":"tracking analytics ga4 google analytics gtm tag manager pixel capi conversions api enhanced conversions utm utms dashboard looker data attribution measurement analytics   tracking measurement ga4 tag manager conversions api dashboards included include service services management agency","q":["what's included in analytics & tracking","what's included in Analytics & Tracking","analytics & tracking","tell me about analytics & tracking","do you do analytics & tracking"],"a":"**Analytics & Tracking**: If tracking is wrong, every decision built on it is wrong too. We set up and audit tracking across every platform, so the algorithms optimise for real results and you see one honest, cross-channel view of performance.\nWhat's included:\n- GA4 and Google Tag Manager setup and audit\n- Meta Pixel + Conversions API with deduplication\n- Google Ads enhanced conversions and offline conversion imports\n- UTM conventions across every paid and owned link\n- Consent banner and tag behaviour for the markets you serve","link":"analytics-tracking.html","lt":"Open Analytics & Tracking","chips":["Why don't Meta, Google and GA4 numbers match?","What is the Meta Conversions API?","lead:Get a free audit"],"tags":["ivia"],"svc":"tracking"},{"id":"faq_tracking_0","title":"Why don't Meta, Google and GA4 numbers match?","k":"why don t meta  google and ga4 numbers match ","q":["Why don't Meta, Google and GA4 numbers match?"],"a":"Each platform uses its own attribution window and rules, and each takes credit for sales it touched. That is why we report blended MER from your actual revenue next to the platform numbers.","link":"analytics-tracking.html","lt":"Open Analytics & Tracking","chips":["What is the Meta Conversions API?","What access do you need for tracking work?","lead:Get a free audit"],"tags":["ivia"],"svc":"tracking"},{"id":"faq_tracking_1","title":"What is the Meta Conversions API?","k":"what is the meta conversions api ","q":["What is the Meta Conversions API?"],"a":"It sends conversion events from your server to Meta alongside the browser Pixel. It recovers events the browser misses, and needs deduplication so each sale is counted once.","link":"analytics-tracking.html","lt":"Open Analytics & Tracking","chips":["Why don't Meta, Google and GA4 numbers match?","What access do you need for tracking work?","lead:Get a free audit"],"tags":["ivia"],"svc":"tracking"},{"id":"faq_tracking_2","title":"What access do you need for tracking work?","k":"what access do you need for tracking work ","q":["What access do you need for tracking work?"],"a":"Usually Google Tag Manager and GA4 access, plus admin access to your store platform or a developer contact for server-side setups. You keep ownership of everything.","link":"analytics-tracking.html","lt":"Open Analytics & Tracking","chips":["Why don't Meta, Google and GA4 numbers match?","What is the Meta Conversions API?","lead:Get a free audit"],"tags":["ivia"],"svc":"tracking"},{"id":"faq_tracking_3","title":"Can you build us a marketing dashboard?","k":"can you build us a marketing dashboard ","q":["Can you build us a marketing dashboard?"],"a":"Yes. A Looker Studio dashboard that combines your ad platforms and analytics, with blended ROAS, MER and CAC, is included in the performance retainer.","link":"analytics-tracking.html","lt":"Open Analytics & Tracking","chips":["Why don't Meta, Google and GA4 numbers match?","What is the Meta Conversions API?","lead:Get a free audit"],"tags":["ivia"],"svc":"tracking"},{"id":"svc_mmm","title":"Marketing Mix Modelling","k":"mmm marketing mix modelling modeling media mix model mix incrementality incremental adstock carryover saturation diminishing returns response curve budget allocation allocate optimiser optimizer meridian robyn pymc geo lift holdout attribution measure measurement marketing mix modelling budget science incrementality response curves geo-lift tests included include service services management agency","q":["what's included in marketing mix modelling","what's included in Marketing Mix Modelling","marketing mix modelling","tell me about marketing mix modelling","do you do marketing mix modelling"],"a":"**Marketing Mix Modelling**: Platform reports tell you what each channel claims. MMM tells you what it actually adds. We model your sales history against every channel, price, promotion and season, then use the response curves to move budget to where the next rupee earns most, and confirm each move with an experiment.\nWhat's included:\n- Data audit and one clean weekly dataset across channels\n- Bayesian MMM with carryover and diminishing returns per channel\n- Validation on held-out weeks and calibration with lift or geo tests\n- Response curves, marginal ROI and a budget optimiser\n- Scenario plans for bigger, smaller or reshaped budgets","link":"marketing-mix-modelling.html","lt":"Open Marketing Mix Modelling","chips":["What is marketing mix modelling?","How is MMM different from GA4 or Ads Manager attribution?","lead:Get a free audit"],"tags":["ivia"],"svc":"mmm"},{"id":"faq_mmm_0","title":"What is marketing mix modelling?","k":"what is marketing mix modelling ","q":["What is marketing mix modelling?"],"a":"A statistical model that links your sales over time to everything that drives them: spend on each channel, prices, promotions, seasonality and more. It estimates how much each channel adds on top of the sales you would have made anyway. It uses aggregated weekly data, not individual user tracking, so cookie loss and privacy changes do not break it.","link":"marketing-mix-modelling.html","lt":"Open Marketing Mix Modelling","chips":["How is MMM different from GA4 or Ads Manager attribution?","How much data do we need?","lead:Get a free audit"],"tags":["ivia"],"svc":"mmm"},{"id":"faq_mmm_1","title":"How is MMM different from GA4 or Ads Manager attribution?","k":"how is mmm different from ga4 or ads manager attribution ","q":["How is MMM different from GA4 or Ads Manager attribution?"],"a":"Attribution follows clicks and views of individual people and gives credit to the touchpoints it can see, so it misses offline sales, cross-device journeys and slow-burn brand effects, and every platform tends to over-claim. MMM works top-down from your total sales, so it sees every channel at once but cannot judge a single ad. We use both, plus experiments to settle disagreements.","link":"marketing-mix-modelling.html","lt":"Open Marketing Mix Modelling","chips":["What is marketing mix modelling?","How much data do we need?","lead:Get a free audit"],"tags":["ivia"],"svc":"mmm"},{"id":"faq_mmm_2","title":"How much data do we need?","k":"how much data do we need ","q":["How much data do we need?"],"a":"Ideally two to three years of weekly sales and spend by channel. Google's Meridian guidance, for example, recommends at least two years of weekly data for regional models and three years for national ones. Spend also needs to have varied over time. If you are not there yet, we start with clean tracking, structured spend tests and geo holdouts, and build the model as history builds up.","link":"marketing-mix-modelling.html","lt":"Open Marketing Mix Modelling","chips":["What is marketing mix modelling?","How is MMM different from GA4 or Ads Manager attribution?","lead:Get a free audit"],"tags":["ivia"],"svc":"mmm"},{"id":"faq_mmm_3","title":"Can one model cover our website, marketplaces and offline sales?","k":"can one model cover our website  marketplaces and offline sales ","q":["Can one model cover our website, marketplaces and offline sales?"],"a":"Yes, and this is where MMM is most useful. Total sales across your website, marketplaces and offline can be the outcome the model explains, and marketplace ads sit in the model as channels alongside Meta and Google. If you have sales by state or city, we can build a regional model and run geo tests.","link":"marketing-mix-modelling.html","lt":"Open Marketing Mix Modelling","chips":["What is marketing mix modelling?","How is MMM different from GA4 or Ads Manager attribution?","lead:Get a free audit"],"tags":["ivia"],"svc":"mmm"},{"id":"faq_mmm_4","title":"How accurate is it?","k":"how accurate is it ","q":["How accurate is it?"],"a":"It is an estimate, so we always show a range, not a single magic number. We check accuracy on weeks the model has not seen, calibrate it against lift or geo tests, and treat every recommendation as a test to confirm before scaling. Where the model is unsure, we say so.","link":"marketing-mix-modelling.html","lt":"Open Marketing Mix Modelling","chips":["What is marketing mix modelling?","How is MMM different from GA4 or Ads Manager attribution?","lead:Get a free audit"],"tags":["ivia"],"svc":"mmm"},{"id":"faq_mmm_5","title":"How often is the model updated?","k":"how often is the model updated ","q":["How often is the model updated?"],"a":"The first model usually takes a few weeks once the data is collected. After that we refresh it on a regular schedule, typically monthly or quarterly, and after any major test, so it keeps learning from what actually happened.","link":"marketing-mix-modelling.html","lt":"Open Marketing Mix Modelling","chips":["What is marketing mix modelling?","How is MMM different from GA4 or Ads Manager attribution?","lead:Get a free audit"],"tags":["ivia"],"svc":"mmm"},{"id":"svc_lifecycle","title":"Email & WhatsApp Marketing","k":"email emails whatsapp retention crm flows flow automation abandoned cart newsletter klaviyo repeat loyalty lifecycle broadcast sms email   whatsapp marketing retention email flows whatsapp campaigns included include service services management agency","q":["what's included in email & whatsapp marketing","what's included in Email & WhatsApp Marketing","email & whatsapp marketing","tell me about email & whatsapp marketing","do you do email & whatsapp marketing"],"a":"**Email & WhatsApp Marketing**: The cheapest customer to win is the one you already have. We set up the automated flows and segmented campaigns that turn first orders into repeat purchases and lift the lifetime value of every customer your ads acquire.\nWhat's included:\n- Welcome, browse- and cart-abandonment, post-purchase and win-back flows\n- Segmented email campaigns and newsletters\n- WhatsApp broadcast and automation setup\n- List growth: pop-ups, offers and lead magnets\n- Monthly retention reporting: repeat rate and revenue per customer","link":"email-whatsapp.html","lt":"Open Email & WhatsApp Marketing","chips":["Which email and WhatsApp tools do you use?","Is WhatsApp marketing allowed?","lead:Get a free audit"],"tags":["ivia"],"svc":"lifecycle"},{"id":"faq_lifecycle_0","title":"Which email and WhatsApp tools do you use?","k":"which email and whatsapp tools do you use ","q":["Which email and WhatsApp tools do you use?"],"a":"Where possible we work with the tools you already use, and recommend one if you are starting fresh, based on your store platform, list size and budget.","link":"email-whatsapp.html","lt":"Open Email & WhatsApp Marketing","chips":["Is WhatsApp marketing allowed?","How quickly do email flows start working?","lead:Get a free audit"],"tags":["ivia"],"svc":"lifecycle"},{"id":"faq_lifecycle_1","title":"Is WhatsApp marketing allowed?","k":"is whatsapp marketing allowed ","q":["Is WhatsApp marketing allowed?"],"a":"Yes, with opt-in. Customers must agree to receive messages, and WhatsApp's business policies apply. We set up opt-in collection and message templates that follow them.","link":"email-whatsapp.html","lt":"Open Email & WhatsApp Marketing","chips":["Which email and WhatsApp tools do you use?","How quickly do email flows start working?","lead:Get a free audit"],"tags":["ivia"],"svc":"lifecycle"},{"id":"faq_lifecycle_2","title":"How quickly do email flows start working?","k":"how quickly do email flows start working ","q":["How quickly do email flows start working?"],"a":"Core flows such as abandoned cart and welcome start working as soon as they are live, because they trigger on your existing traffic. Campaign results grow as the list grows.","link":"email-whatsapp.html","lt":"Open Email & WhatsApp Marketing","chips":["Which email and WhatsApp tools do you use?","Is WhatsApp marketing allowed?","lead:Get a free audit"],"tags":["ivia"],"svc":"lifecycle"},{"id":"faq_lifecycle_3","title":"Do you write the emails?","k":"do you write the emails ","q":["Do you write the emails?"],"a":"Yes. Copy, design and setup are included, and you approve everything before it goes live.","link":"email-whatsapp.html","lt":"Open Email & WhatsApp Marketing","chips":["Which email and WhatsApp tools do you use?","Is WhatsApp marketing allowed?","lead:Get a free audit"],"tags":["ivia"],"svc":"lifecycle"},{"id":"acos","title":"ACOS","k":"acos advertising cost of sale what is acos good acos meaning formula","q":["what is acos","what is a good acos","acos meaning"],"a":"**ACOS** (advertising cost of sale) = ad spend ÷ ad-attributed sales × 100. Lower is more efficient.\nA \"good\" ACOS depends on your margin: compare it to your **breakeven ACOS**, which equals your profit margin before ad costs. With a 30% margin, anything above 30% ACOS loses money on that sale.","link":"marketplaces.html","lt":"Amazon & marketplaces","chips":["What is TACOS?","Breakeven ACOS?","Calculate my target CPC"],"tags":["ivia","mkt"]},{"id":"tacos","title":"TACOS","k":"tacos total advertising cost of sale what is tacos organic","q":["what is tacos","acos vs tacos","difference between acos and tacos"],"a":"**TACOS** = ad spend ÷ **total** sales (ads + organic). If TACOS falls while sales grow, ads are building organic rank. If it rises, you're buying sales rather than building them. We judge Amazon accounts on TACOS and organic rank, SKU by SKU.","link":"blog-acos-vs-tacos.html","lt":"Read: ACOS vs TACOS","chips":["What is ACOS?","Calculate my target CPC"],"tags":["ivia","mkt"]},{"id":"roas","title":"ROAS","k":"roas return on ad spend roi what is roas good roas","q":["what is roas","what is a good roas","roas vs acos"],"a":"**ROAS** = revenue ÷ ad spend. It's the inverse of ACOS: [[ROAS = 1 ÷ ACOS]] so 25% ACOS = 4× ROAS. A good ROAS is one above your **breakeven ROAS** (1 ÷ margin). We also report blended **MER**, which can't double-count.","chips":["Breakeven ROAS?","What is MER?"],"tags":["ivia","mkt"]},{"id":"breakeven","title":"Breakeven ROAS & ACOS","k":"breakeven break even roas acos profit floor margin minimum return","q":["what is breakeven roas","breakeven acos","how do i calculate breakeven roas"],"a":"**Breakeven ROAS = 1 ÷ margin** (margin before ad costs). **Breakeven ACOS = that margin.** Example: a 40% margin means breakeven ROAS of 2.5× and breakeven ACOS of 40%. Tell me your margin and I'll work it out.","chips":["Breakeven at 40% margin","What is MER?"],"tags":["ivia","mkt"]},{"id":"mer","title":"MER","k":"mer marketing efficiency ratio blended roas total revenue total spend","q":["what is mer","blended roas"],"a":"**MER** (marketing efficiency ratio) = **total revenue ÷ total marketing spend**, across every channel. Platforms each take credit for the same sale; MER can't double-count, so it's the number budget decisions are made on.","link":"blog-roas-mer-cac.html","lt":"Read: ROAS vs MER vs CAC","chips":["What is CAC?","Why don't platform numbers match?"],"tags":["ivia"]},{"id":"cac","title":"CAC","k":"cac customer acquisition cost new customer cost per customer","q":["what is cac","new customer cac"],"a":"**New-customer CAC** = marketing spend ÷ **new** customers. It shows what each genuinely new customer costs, separate from retargeting and repeat buyers, and how long their repeat purchases take to pay it back.","link":"blog-roas-mer-cac.html","lt":"Read: ROAS vs MER vs CAC","chips":["What is MER?","Email & WhatsApp marketing"],"tags":["ivia"]},{"id":"tcpc","title":"Target CPC formula","k":"target cpc bid formula calculate bids bidding how much to bid cost per click calculated","q":["calculate my target cpc","what should i bid","how do you calculate bids"],"a":"We calculate bids instead of guessing: [[Target CPC = Target ACOS × CVR × Price]]Example: 30% × 10% × ₹999 = **₹29.97**. Send me your price, target ACOS and conversion rate and I'll do it for you.","link":"bidvista.html#calc","lt":"Open the calculators","chips":["Price 999, ACOS 30%, CVR 10%","What is CVR?"],"tags":["ivia","mkt"]},{"id":"cvr","title":"Conversion rate","k":"cvr conversion rate cr unit session percentage what is cvr","q":["what is cvr","what is conversion rate"],"a":"**Conversion rate (CVR)** = orders ÷ clicks (on Amazon, orders ÷ sessions or clicks for ads). It's a key input to bids: higher CVR means each click is worth more. Better listing images, reviews and price usually move it most.","chips":["Calculate my target CPC","Creative & Content"],"tags":["ivia","mkt"]},{"id":"negatives","title":"Negative keywords","k":"negative negatives keywords wasted spend irrelevant search terms exclude","q":["what are negative keywords","how do you reduce wasted spend"],"a":"**Negative keywords** stop your ads showing for irrelevant searches. We review search terms weekly and negate terms that spend without selling. In our audits, this alone often recovers a meaningful share of spend.","link":"blog-negative-keywords.html","lt":"Read: negative keywords","chips":["What is search-term harvesting?","lead:Audit my account"],"tags":["ivia","mkt"]},{"id":"harvest","title":"Search-term harvesting","k":"search term harvesting harvest exact match discovery auto campaign move","q":["what is search term harvesting"],"a":"Search-term harvesting moves the searches that convert in **discovery** (auto and broad) campaigns into **exact-match** campaigns with their own bids, while negating them in discovery so they don't compete.","link":"blog-search-term-harvesting.html","lt":"Read the guide","chips":["What is the three-tier structure?"],"tags":["ivia","mkt"]},{"id":"tiers","title":"Three-tier campaign structure","k":"three tier campaign structure architecture discovery qualification dominance campaigns setup account structure","q":["what is the three tier structure","how do you structure amazon campaigns"],"a":"Our Amazon architecture has three tiers:\n- **Discovery**: auto and broad campaigns that find new searches\n- **Qualification**: phrase and tested terms proving they convert\n- **Dominance**: exact-match winners with calculated bids\nNegatives keep each tier clean.","link":"blog-campaign-structure.html","lt":"Read: campaign structure","chips":["What is search-term harvesting?","lead:Audit my account"],"tags":["ivia","mkt"]},{"id":"launch","title":"Product launch","k":"launch new product new listing asin rank vine reviews 60 day playbook","q":["how do you launch a new product","launch on amazon"],"a":"Our **60-day launch playbook**: listing readiness, keyword selection, launch bids, review programmes such as Vine, and milestones to reach organic rank. One skincare launch went from 0 to 12 page-1 keywords in 75 days.","link":"blog-product-launch.html","lt":"Read: launch playbook","chips":["lead:Plan my launch","What is TACOS?"],"tags":["ivia","mkt"]},{"id":"portfolio","title":"SKU portfolio tiers","k":"portfolio sku skus tier scale sustain reduce sunset profitability products","q":["how do you manage many skus"],"a":"Every SKU is tiered **Scale / Sustain / Reduce / Sunset** from its margin and performance, so budget follows profit instead of being shared evenly.","link":"blog-portfolio-management.html","lt":"Read the guide","tags":["ivia","mkt"]},{"id":"sb","title":"Sponsored Brands","k":"sponsored brands video headline store brand ads","q":["what are sponsored brands ads"],"a":"**Sponsored Brands** show your logo, headline and several products (or a video) at the top of search. They're great for brand searches and category defence once Sponsored Products are working.","link":"blog-sponsored-brands.html","lt":"Read the guide","tags":["ivia","mkt"]},{"id":"wasted","title":"Wasted spend","k":"wasted spend waste leak money burning budget losing money inefficient","q":["how do i stop wasting ad spend","where is my budget going"],"a":"Wasted spend usually hides in three places: **irrelevant search terms**, **campaigns sharing budgets across products with different margins**, and **bids no one has recalculated**. The free audit quantifies it for your accounts.","link":"blog-wasted-spend.html","lt":"Read: finding wasted spend","chips":["lead:Audit my account","What are negative keywords?"],"tags":["ivia","mkt"]},{"id":"capi","title":"Conversions API","k":"conversions api capi server side pixel deduplication dedupe events","q":["what is conversions api","what is capi"],"a":"It sends conversion events from your server to Meta alongside the browser Pixel. It recovers events the browser misses, and needs deduplication so each sale is counted once.","link":"analytics-tracking.html","lt":"Analytics & Tracking","chips":["Why don't platform numbers match?"],"tags":["ivia"]},{"id":"ga4","title":"GA4 & Tag Manager","k":"ga4 google analytics tag manager gtm setup events","q":["do you set up ga4","google analytics setup"],"a":"Yes. We set up and audit **GA4** and **Google Tag Manager**, with purchases or leads recorded with the right value, consistent UTMs, and a Looker Studio dashboard on top.","link":"analytics-tracking.html","lt":"Analytics & Tracking","tags":["ivia"]},{"id":"pmaxc","title":"Performance Max","k":"performance max pmax google shopping brand exclusions asset groups","q":["what is performance max","should we run pmax"],"a":"Usually both, with clear roles. Search gives control over exactly which queries you pay for; Performance Max can find extra conversions across Google's inventory. We run PMax with brand exclusions and a clean feed so it doesn't simply take credit for brand searches.","link":"google-ads.html","lt":"Google Ads","tags":["ivia"]},{"id":"advplus","title":"Advantage+","k":"advantage+ advantage plus shopping campaigns asc meta automation","q":["what is advantage plus"],"a":"Often yes for e-commerce, alongside a separate creative-testing setup so you still learn which concepts win. We decide after looking at your catalog, data volume and how much control you need over new versus returning customers.","link":"meta-ads.html","lt":"Meta Ads","tags":["ivia"]},{"id":"learning","title":"Learning phase","k":"learning phase limited learning ad set exit learning 50 conversions","q":["what is the learning phase"],"a":"Meta's **learning phase** is the period after launch or big edits while delivery is optimised; ad sets need roughly 50 optimisation events a week to exit it. That's why we consolidate into fewer, better-funded ad sets.","link":"blog-meta-ads-structure.html","lt":"Read: Meta account structure","tags":["ivia"]},{"id":"hook","title":"Hook rate & creative testing","k":"hook rate hold rate thumb stop creative testing test creatives fatigue winner","q":["what is hook rate","how do you test creatives"],"a":"**Hook rate** = 3-second video plays ÷ impressions: does the opening stop the scroll? **Hold rate** = ThruPlays ÷ 3s plays: does the story keep them? We test new concepts every month with clear scale-or-kill rules on cost per result.","link":"blog-creative-testing.html","lt":"Read: creative testing","chips":["Do you make the ads?","Creative & Content"],"tags":["ivia"]},{"id":"utm","title":"UTM parameters","k":"utm utms parameters campaign tagging links source medium","q":["what are utms"],"a":"UTM parameters tag each link with its source, medium and campaign, so analytics can tell traffic apart. We set one naming convention across every paid and owned link.","link":"analytics-tracking.html","lt":"Analytics & Tracking","tags":["ivia"]},{"id":"cro","title":"Conversion rate optimisation","k":"cro conversion rate optimisation optimization landing page ab test a/b testing improve conversions","q":["what is cro","how can i improve my conversion rate"],"a":"Doubling your conversion rate halves your cost per customer on every channel at once. We find drop-off points with analytics, heatmaps and recordings, then A/B test headlines, offers and layouts.","link":"websites.html","lt":"Websites & CRO","chips":["Do you build on Shopify?","lead:Audit my funnel"],"tags":["ivia"]},{"id":"flows","title":"Email flows","k":"flow flows automation abandoned cart welcome win back post purchase browse abandonment","q":["which email flows do you set up"],"a":"The core automations: **welcome**, **browse and cart abandonment**, **post-purchase** and **win-back**, on email and WhatsApp. They work from day one because they trigger on your existing traffic.","link":"email-whatsapp.html","lt":"Email & WhatsApp","tags":["ivia"]},{"id":"bv_what","title":"What is Bidvista","k":"bidvista what is bidvista ai bot marketplace ai co pilot tool software product app","q":["what is bidvista","what can bidvista do","tell me about bidvista"],"a":"**Bidvista** is ivia's marketplace AI co-pilot for Amazon (and later Flipkart) advertisers, now in development. It's being built to:\n- **Search-term mining** (building now): Reads your search-term reports and flags the terms that spend without selling, and the ones worth moving into exact match.\n- **Calculated bids** (building now): Suggests a bid for every keyword from Target ACOS × conversion rate × price, adjusted for placement.\n- **Negative keyword finder** (building now): Spots irrelevant and wasteful searches and proposes negatives, with the spend each one cost you.\n- **TACOS & organic view** (planned): Shows whether ads are building organic sales or just buying them, SKU by SKU.\n- **SKU portfolio tiers** (planned): Groups products into Scale, Sustain, Reduce and Sunset from margin and performance.\n- **Launch co-pilot** (planned): Guides new products through the first 60 days: keywords, launch bids and milestones.\nYou approve every change.","link":"bidvista.html","lt":"Open Bidvista","chips":["When does it launch?","lead:Join early access","Calculate my target CPC"],"tags":["bv","mkt","ivia"]},{"id":"bv_live","title":"Is Bidvista live","k":"bidvista live launch when available release date beta ready out now","q":["when does it launch","is bidvista live","when will bidvista launch"],"a":"Not yet. Bidvista is in development, and early-access members will be the first invited when the beta opens. The calculators on this page are free to use today.","link":"bidvista.html#waitlist","lt":"Join the waitlist","chips":["lead:Join early access","What can Bidvista do?"],"tags":["bv","mkt"],"act":"lead"},{"id":"bv_join","title":"Bidvista early access","k":"bidvista waitlist early access join sign up beta access invite register","q":["join early access","how do i join the waitlist","sign up for bidvista"],"a":"Great! Leave your details below and you'll be first in line when the Bidvista beta opens. You can also use the form on the [Bidvista page](bidvista.html#waitlist).","chips":["lead:Join early access"],"tags":["bv","mkt"],"act":"lead"},{"id":"bv_price","title":"Bidvista pricing","k":"bidvista price pricing cost free paid subscription","q":["how much will bidvista cost","is bidvista free","how much does it cost","pricing","price"],"a":"Pricing has not been set yet. Early-access members will hear first, before public launch.","chips":["lead:Join early access"],"tags":["bv","mkt"]},{"id":"bv_mkt","title":"Bidvista marketplaces","k":"bidvista marketplaces support which","q":["which marketplaces will bidvista support"],"a":"Amazon first, starting with Amazon India and the other markets ivia already manages (US, UK and UAE). Flipkart and other marketplaces are planned.","tags":["bv","mkt"]},{"id":"bv_auto","title":"Does Bidvista change campaigns","k":"bidvista automatic automatically change campaigns safe control approve autopilot","q":["will bidvista change my campaigns automatically","is bidvista safe"],"a":"The plan is for Bidvista to suggest and for you to approve. Every recommendation will come with the reasoning and numbers behind it. It works from your reports and never needs your password.","tags":["bv","mkt"]},{"id":"bv_ivia","title":"Bidvista and ivia","k":"bidvista ivia part relation same company related owner","q":["is bidvista part of ivia"],"a":"Yes. Bidvista is ivia's marketplace product, built on the same playbook ivia's team uses on the Amazon accounts it manages. It focuses only on marketplaces.","tags":["bv","mkt","ivia"]},{"id":"bv_now","title":"Amazon help now","k":"help amazon ads managed service team manage my amazon account","q":["can i get help with my amazon ads now"],"a":"Yes. ivia's marketplace team manages Amazon and Flipkart advertising today. Start with an audit on the marketplaces page, or message us on WhatsApp.","link":"marketplaces.html","lt":"Amazon & marketplaces","chips":["lead:Audit my Amazon account"],"tags":["bv","mkt"],"act":"lead"},{"id":"mmm_data","title":"Data needed for MMM","k":"mmm data need needed require requirements history weeks years enough how much ready readiness marketing mix modelling modeling for mmm","q":["how much data do you need for mmm","how much data do you need for marketing mix modelling","what data do you need for mmm","how much history do we need","is my data enough for marketing mix modelling"],"a":"Ideally two to three years of weekly sales and spend by channel. Google's Meridian guidance, for example, recommends at least two years of weekly data for regional models and three years for national ones. Spend also needs to have varied over time. If you are not there yet, we start with clean tracking, structured spend tests and geo holdouts, and build the model as history builds up. You can check where you stand with the readiness check on the MMM page.","link":"marketing-mix-modelling.html","lt":"Marketing Mix Modelling","chips":["What is MMM?","lead:Check if MMM fits us"],"tags":["ivia"]},{"id":"mmm_adstock","title":"Adstock / carryover","k":"adstock carryover decay lag lagged delayed effect lasts after week","q":["what is adstock","what is carryover in mmm"],"a":"**Adstock** (carryover) is how long an ad keeps working after the week it runs: people remember, search later, buy next payday. An MMM learns this decay for every channel, so slow-burn brand media like video gets fair credit. You can play with it on the [MMM page](marketing-mix-modelling.html#how).","link":"marketing-mix-modelling.html","lt":"Marketing Mix Modelling","chips":["What is marginal ROI?","What is MMM?"],"tags":["ivia"]},{"id":"mmm_mroi","title":"Marginal ROI and saturation","k":"marginal mroi saturation saturated diminishing returns next rupee response curve curves","q":["what is marginal roi","what are diminishing returns"],"a":"**Marginal ROI** is the return on the *next* ₹1, not the average. Every channel saturates: the first rupees reach the keenest buyers, later ones reach people less likely to buy. A channel can have a fine average ROI and a poor next rupee. MMM draws these response curves so budget moves to where the next rupee still earns. Try the [budget lab](marketing-mix-modelling.html#tool).","link":"marketing-mix-modelling.html","lt":"Marketing Mix Modelling","chips":["What is adstock?","lead:Check if MMM fits us"],"tags":["ivia"]},{"id":"mmm_incr","title":"Incrementality","k":"incrementality incremental lift causal holdout geo test experiment experiments conversion lift","q":["what is incrementality","what is a geo lift test"],"a":"**Incrementality** means sales that happened *because of* an ad, which would not have happened without it. Platforms report every sale they touched; incrementality strips out the ones you would have made anyway. We measure it with holdout and geo-lift tests and use the results to calibrate the marketing mix model.","link":"marketing-mix-modelling.html","lt":"Marketing Mix Modelling","chips":["What is MMM?","How is MMM different from attribution?"],"tags":["ivia"]},{"id":"mmm_cost","title":"MMM pricing","k":"mmm cost price pricing fee fees charge charges how much quote budget expensive","q":["what does mmm cost","how much does marketing mix modelling cost","mmm pricing"],"a":"There's no fixed price list for MMM. It depends on how many channels and markets you run, how clean your data is and whether we add experiments. We start with a free readiness check, then quote a fixed scope. If you're not ready for a model yet, we'll say so and suggest the cheaper first step.","link":"marketing-mix-modelling.html","lt":"Marketing Mix Modelling","chips":["How much data do we need?","lead:Check if MMM fits us"],"tags":["ivia"]},{"id":"mmm_tools","title":"MMM tools we use","k":"meridian robyn pymc pymc-marketing tool tools software framework open source python r bayesian","q":["do you use meridian or robyn","which mmm tool do you use"],"a":"We build models with open-source frameworks such as **Google Meridian**, **Meta Robyn** or **PyMC-Marketing**, chosen for your data and channels. All three model carryover and diminishing returns, and can be calibrated with experiment results. You own the model and its outputs.","link":"marketing-mix-modelling.html","lt":"Marketing Mix Modelling","chips":["How much data do we need?","lead:Check if MMM fits us"],"tags":["ivia"]},{"id":"measure","title":"How we measure success","k":"measure success kpi kpis metrics numbers judge target targets","q":["how do you measure success"],"a":"We agree targets in writing before launch and report on numbers that can't double-count: **MER** (total revenue ÷ total spend), **breakeven ROAS** (1 ÷ margin) and **new-customer CAC**. On Amazon we add **TACOS** and organic rank.","link":"case-studies.html","lt":"See case studies","chips":["What is MER?","What is TACOS?"],"tags":["ivia"]}],"start":{"default":["What do you do?","How much does it cost?","lead:Get a free audit","What is Bidvista?"],"bidvista":["What can Bidvista do?","When does it launch?","Calculate my target CPC","lead:Join early access"],"contact":["How fast do you reply?","What access do you need?","What's in the free audit?","wa:Chat on WhatsApp"],"cases":["How do you measure success?","Do you guarantee results?","lead:Get a free audit"],"blog":["What is TACOS?","What is MER?","Calculate my target CPC","lead:Get a free audit"],"meta":["What's included in Meta Ads?","What budget do I need for Meta ads?","Do you make the ads too?","lead:Get a free Meta audit"],"google":["What's included in Google Ads?","Search or Performance Max: which should we run?","Should we bid on our own brand name?","lead:Get a free Google audit"],"amazon":["What's included in Amazon & Marketplaces?","Which marketplaces do you manage?","What is the difference between ACOS and TACOS?","lead:Get a free Amazon audit"],"creative":["What's included in Creative & Content?","Do you work with creators and influencers?","How many new creatives do we need each month?","lead:Talk to the team"],"social":["What's included in Social Media Management?","Which social platforms do you manage?","Do we approve posts before they go live?","lead:Talk to the team"],"seo":["What's included in SEO & Content?","How long does SEO take?","Do you write the SEO content?","lead:Get a free SEO audit"],"web":["What's included in Websites & Landing Pages?","Do you build on Shopify and WordPress?","Do we need a full website redesign?","lead:Talk to the team"],"tracking":["What's included in Analytics & Tracking?","Why don't Meta, Google and GA4 numbers match?","What is the Meta Conversions API?","lead:Get a free Analytics audit"],"mmm":["What's included in Marketing Mix Modelling?","What is marketing mix modelling?","How is MMM different from GA4 or Ads Manager attribution?","lead:Check if MMM fits us"],"lifecycle":["What's included in Email & WhatsApp Marketing?","Which email and WhatsApp tools do you use?","Is WhatsApp marketing allowed?","lead:Talk to the team"]},"fallback":{"ivia":"I'm not sure I have a good answer to that yet. I can help with ivia's services, pricing, results, Bidvista or marketing terms like ROAS and ACOS, or the team can answer directly.","bidvista":"I'm not sure about that one. I can explain ACOS, TACOS, bids, negatives and launches, run the bid formulas, or tell you about Bidvista early access."},"svcNames":{"meta":"Meta Ads","google":"Google Ads","amazon":"Amazon & Marketplaces","creative":"Creative & Content","social":"Social Media Management","seo":"SEO & Content","web":"Websites & Landing Pages","tracking":"Analytics & Tracking","mmm":"Marketing Mix Modelling","lifecycle":"Email & WhatsApp Marketing"}};
